import React, { useState } from 'react';

export default function Quiz({ onSubmit }) {
  const [answers, setAnswers] = useState({
    style: '',
    decade: '',
    item: ''
  });

  const handleChange = (e) => {
    setAnswers({ ...answers, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(answers);
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>📝 Fashion Quiz</h2>

      <label>Preferred Style:</label>
      <select name="style" onChange={handleChange} required>
        <option value="">Select</option>
        <option value="Modern Classic">Modern Classic</option>
        <option value="Retro Streetwear">Retro Streetwear</option>
        <option value="Boho Chic">Boho Chic</option>
      </select>

      <br /><br />

      <label>Favorite Decade:</label>
      <select name="decade" onChange={handleChange} required>
        <option value="">Select</option>
        <option value="2020s">2020s</option>
        <option value="90s">90s</option>
        <option value="70s">70s</option>
      </select>

      <br /><br />

      <label>Go-to Clothing Item:</label>
      <select name="item" onChange={handleChange} required>
        <option value="">Select</option>
        <option value="jeans">Jeans</option>
        <option value="jacket">Jacket</option>
        <option value="maxi dress">Maxi Dress</option>
      </select>

      <br /><br />

      <button type="submit">Get My Style DNA</button>
    </form>
  );
}
